"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["12341"],{72405(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.codigo_obrigatorio","status":422,"titulo":"C\xf3digo do modelo de formul\xe1rio \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.codigo_obrigatorio","requisitos":[],"oQueAconteceu":["A cria\xe7\xe3o de um modelo de formul\xe1rio (`POST /api/configuracao/admin/modelos-formulario`) veio com o campo `codigo` presente, mas vazio ou s\xf3 com espa\xe7os. O c\xf3digo \xe9 o que identifica o modelo no cadastro e o distingue dos outros modelos do mesmo uso; ele \xe9 imut\xe1vel depois da cria\xe7\xe3o.","Este c\xf3digo n\xe3o cobre o `codigo` ausente do JSON nem enviado como `null`. O corpo da cria\xe7\xe3o declara o c\xf3digo como texto n\xe3o anul\xe1vel, e o ASP.NET Core recusa o campo ausente ou nulo na valida\xe7\xe3o do modelo, com 400, antes de o pedido chegar \xe0s regras do Uni+. Essa recusa n\xe3o tem c\xf3digo do cat\xe1logo de erros. S\xf3 o c\xf3digo presente e em branco responde 422 com o c\xf3digo desta p\xe1gina.","A recusa vem na lista `errors` da resposta, com `field` igual a `codigo`. Quando o conte\xfado do modelo tamb\xe9m tem recusas, as do conte\xfado v\xeam antes na lista, e a resposta leva todas. Nada \xe9 gravado."],"comoResolver":["Informe um c\xf3digo de at\xe9 60 caracteres e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);